    constructor(C _c) {
        c = _c;
    }

    // We take as parameters a bytes32 guess and an amount to send when locking (must be 1 ether to succeed)
    // and a dummy extra param unused to vary inputs if needed.
    function run(bytes32 guess, uint lockAmount, uint unused) public payable {
        require(address(this).balance >= lockAmount);
        // Ensure we try to lock in a guess. Capture whether lockInGuess reverted.
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guess) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // If the lock succeeded, then the contract should have recorded a future block number (>0).
        // We can observe that by attempting to call settle immediately: the contract requires block.number > storedBlock,
        // so settle must revert if called too early. We record whether immediate settle reverts.
        bool immediateSettleReverted;
        try c.settle() {
            immediateSettleReverted = false;
        } catch {
            immediateSettleReverted = true;
        }

        // If lock reverted, nothing changed in c for this caller: immediateSettleReverted should be true (since no guess stored, settle reverts due to require)
        // If lock succeeded, immediateSettleReverted must be true because settle requires block.number > storedBlock (we called in same tx)
        assert(lockReverted ? immediateSettleReverted : immediateSettleReverted);
    }

    receive() external payable {}
}

