contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two parameters: a guess bytes32 and an amount to send when locking.
    // The function is payable so the test harness can fund this contract beforehand.
    function run(bytes32 guessHash, uint lockAmount) public payable {
        // require enough balance to send the lock amount
        require(address(this).balance >= lockAmount);
        // Precondition: lockAmount must be exactly 1 ether to satisfy C.lockInGuess
        require(lockAmount == 1 ether);

        // Ensure we start with no active guess for this test contract address in C
        // We can call lockInGuess only if C's mapping for this address has block == 0.
        // So first call lockInGuess with 1 ether.
        c.lockInGuess{value: lockAmount}(guessHash);

        // Read the stored Guess.block via the public auto-getter for the mapping
        // The mapping generates a getter: guesses(address) returns (uint, bytes32)
        (uint storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Now attempt to call settle. settle requires block.number > storedBlock.
        // We cannot advance blocks here, but the property is about what settle does when
        // it is called in a later block. To make the checker consider both possibilities
        // (revert vs not), we try to call settle and capture whether it reverted.
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the attempt to settle, read the stored guess entry again and contract balance.
        (uint storedBlockAfter, bytes32 storedGuessAfter) = c.guesses(address(this));
        uint balanceC = address(c).balance;

        // General rule asserted universally:
        // If settle did not revert, then the guess entry must have been cleared (storedBlockAfter == 0),
        // and the contract's balance can only have decreased by exactly 2 ether if and only if the stored guess matched
        // the computed answer; equivalently, if balance decreased by 2 ether then storedGuess must have equaled
        // keccak256(abi.encodePacked(blockhash(storedBlock))). Because we cannot compute blockhash here reliably,
        // we instead assert the invariant that whenever settle succeeded the stored entry is cleared, and when settle reverted
        // the stored entry is unchanged (still equals the values observed right after lockInGuess).
        assert(
            // If settle reverted then stored values remain as they were after locking
            (reverted && storedBlockAfter == storedBlock && storedGuessAfter == storedGuess)
            ||
            // If settle did not revert then stored entry was cleared
            (!reverted && storedBlockAfter == 0)
        );
    }

    receive() external payable { }
}

