    // The test will (1) call lockInGuess with the given hash and value, recording whether it reverted,
    // then (2) call settle and record whether it reverted, and finally assert a general property
    // that whenever lockInGuess succeeded and settle succeeded (did not revert), the contract's
    // stored block for this caller is reset to 0 (the guess record is cleared).

    function run(bytes32 hash, uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test call");

        // Initially ensure we have no active guess by trying to reset via calling settle (may revert if none).
        // We don't care about this call's outcome; we only observe the subsequent behaviors.

        bool lockReverted;
        bool settleReverted;

        // Attempt to lock a guess with provided amount
        try c.lockInGuess{value: amount}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Attempt to settle immediately afterwards. According to contract logic, settle requires current
        // block > stored block, so normally this may revert. But the property we assert only concerns the case
        // when both calls succeeded (did not revert).
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Observe the stored Guess.block via the public getter for the mapping: C.guesses is public, so
        // Solidity generates a getter guesses(address) returning (uint, bytes32). We read the first value.
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // General rule asserted: If lockInGuess did not revert (it succeeded and thus created a guess record),
        // and settle did not revert (it executed), then the stored block must be 0 afterwards (the record was cleared).
        // This captures that a successful settle clears the guess state for the caller.
        assert(!( (!lockReverted && !settleReverted) && !(storedBlock == 0) ));
    }

    // Allow receiving Ether so the test can fund calls
    receive() external payable {}
}

