    // - guessHash: the bytes32 value to pass to lockInGuess
    // - lockAmount: amount of wei to send to lockInGuess (must be exactly 1 ether for success)
    function run(bytes32 guessHash, uint lockAmount) public payable {
        // Precondition: we will only attempt the meaningful scenario when lockAmount == 1 ether
        require(lockAmount == 1 ether);
        // Ensure this test contract has enough balance to send lockAmount
        require(address(this).balance >= lockAmount);

        // Record balances before interaction
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        // Call lockInGuess (this changes c's state). This is a top-level statement and may revert.
        // Let it revert naturally if parameters/state cause revert; we catch that below by checking balances.
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint afterLockC = address(c).balance;
        uint afterLockMe = address(this).balance;

        // Try to call settle (it may revert depending on blocks); record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint afterSettleC = address(c).balance;
        uint afterSettleMe = address(this).balance;

        // General rule (single assert):
        // If lockInGuess reverted, nothing changed in balances.
        // If lockInGuess succeeded (we paid 1 ether): c.balance increased by exactly 1 ether and our balance decreased by exactly 1 ether.
        // Furthermore, after a successful lock, if settle later does not revert, then this test's balance cannot be lower than its post-lock balance unless it received the 2 ether payout (i.e., any decrease must be offset by receiving 2 ether).
        assert(
            // Case A: lock reverted -> balances unchanged and we cannot have gained/ lost funds
            (lockReverted && afterLockC == beforeC && afterLockMe == beforeMe && afterSettleC == beforeC && afterSettleMe == beforeMe)
            ||
            // Case B: lock succeeded -> c gained 1 ether and we lost 1 ether at lock time
            (!lockReverted
                && afterLockC == beforeC + 1 ether
                && afterLockMe == beforeMe - 1 ether
                // Now consider settle outcome:
                && (
                    // If settle reverted: balances remain same as after lock
                    (settleReverted && afterSettleC == afterLockC && afterSettleMe == afterLockMe)
                    ||
                    // If settle succeeded: we either received the 2 ether payout (net +1 ether vs before) OR balances reflect no net unauthorized loss
                    (!settleReverted && (
                        // Received payout: our balance is beforeMe + 1 ether (we locked -1 then got +2)
                        afterSettleMe == beforeMe + 1 ether
                        && afterSettleC + 1 ether == beforeC // contract paid out 2 ether net decrease by 2: beforeC -> afterSettleC == beforeC - 2 => afterSettleC + 1 == beforeC -1? To remain conservative, require contract decreased at least by 1 ether relative to afterLockC
                    ) ||
                        // Or at least ensure we did not lose additional funds beyond the locked ether (conservative check)
                        (afterSettleMe >= afterLockMe)
                    ))
                )
            )
        );
    }

    receive() external payable {}
}

