    // params:
    // bytes32 guessHash - the hash to lock in
    // uint lockValue - amount of wei to send when calling lockInGuess (should be 1 ether to succeed)
    // uint extraCalls - number of empty blocks to simulate by making dummy calls that advance block.number (cannot actually mine blocks here, but we can attempt settle only after lockInGuess with block constraint enforced by contract)
    function run(bytes32 guessHash, uint lockValue) public payable {
        require(address(this).balance >= lockValue);
        // Record balances before any interactions
        uint beforeContract = address(c).balance;
        uint beforeThis = address(this).balance;

        // Try to lock in a guess; capture whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After lock attempt, record balances
        uint midContract = address(c).balance;
        uint midThis = address(this).balance;

        // Now try to call settle; it may revert if block conditions not met or no guess locked
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint afterContract = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant to assert:
        // If lockInGuess succeeded (so caller had an active guess), then after settle (whether it reverted or not) one of the following must hold:
        // - If settle reverted then either the lock had not been placed or block preconditions failed; but monetary totals must not change (contract+this unchanged from mid to after)
        // - If settle did not revert then total ether (contract + this) must equal midContract + midThis (no loss/gain), and if this contract received 2 ether from c then the difference reflects that
        // We express a general conservation: (afterContract + afterThis) == (midContract + midThis)
        // Additionally: if lockReverted then mid balances equal before balances. This avoids trivializing by having external ether magically appear.

        assert((lockReverted && midContract == beforeContract && midThis == beforeThis && afterContract == midContract && afterThis == midThis)
               || (!lockReverted && (afterContract + afterThis) == (midContract + midThis)));
    }

    receive() external payable {}
}

